function t(r){return r==="NORMAL"||Number(r)===1}function u(r){return r==="DISABLED"||Number(r)===0}function i(r){return t(r)?"账号正常":u(r)?"账号停用":"状态未知"}function o(r){if(!r)return"新用户";const n=new Date(r);return Number.isNaN(n.getTime())?"新用户":`${n.getFullYear()} 年 ${n.getMonth()+1} 月加入`}function c(r){return["1","2","3","4","6"].reduce((n,e)=>n+(Number(r[e])||0),0)}export{i as a,t as i,o as j,c as t};
